const policy = {
  timezone: 'Asia/Riyadh',
  verifyAfterMs: 8000,
  unlockDelayMs: 600,
  retryDelaysSec: [5, 15, 60, 180, 300],
  keepRetrying: true,
  guardianStallMinutes: 5,
  journalLimit: 500,
  alarmPolicy: {
    enabled: false,
    maxAttempts: null,
    maxMismatchMinutes: null
  }
};
flow.set('devxx_policy', policy);
node.status({fill:'green',shape:'dot',text:'Policy loaded'});
msg.auditRecord = {
  ts: Date.now(), deviceId: 'DEVXX', channel: 'actual',
  sourceLayer: 'policy', eventType: 'policy_loaded',
  phase: 'boot', desiredMode: null, requiredBreakerState: null,
  actualBreakerState: null, healthMode: null,
  ticketId: null, attemptNo: 0, result: 'ok', reasonCode: 'policy_initialized'
};
return [null, msg];

const rows = Array.isArray(msg.payload) ? msg.payload : [msg.payload];
const out = [];
for (const row of rows) {
  if (!row || String(row.Enabled || '0') !== '1') continue;
  const day = String(row.Day || '').trim().toLowerCase();
  const start = String(row.Start || '').trim();
  const end = String(row.End || '').trim();
  const mode = String(row.Mode || 'run').trim().toLowerCase();
  if (!day || !start || !end) continue;
  out.push({ id: `${day}_${start}_${end}_${mode}`, day, start, end, mode, enabled: true });
}
flow.set('devxx_schedule', out);
node.status({fill:'green',shape:'dot',text:`${out.length} windows loaded`});
msg.auditRecord = {
  ts: Date.now(), deviceId: 'DEVXX', channel: 'expected',
  sourceLayer: 'scenario', eventType: 'schedule_translated',
  phase: (flow.get('devxx_state') || {}).phase || 'boot',
  desiredMode: null, requiredBreakerState: null,
  actualBreakerState: null, healthMode: null,
  ticketId: null, attemptNo: 0,
  result: `windows:${out.length}`, reasonCode: 'csv_to_canonical'
};
return [null, {auditRecord: msg.auditRecord}];

const policy = flow.get('devxx_policy') || { timezone: 'Asia/Riyadh' };
const schedule = flow.get('devxx_schedule') || [];
const now = new Date();
const local = new Date(now.toLocaleString('en-US', { timeZone: policy.timezone || 'Asia/Riyadh' }));
const dayNames = ['sunday','monday','tuesday','wednesday','thursday','friday','saturday'];
const currentDay = dayNames[local.getDay()];
const nowMin = local.getHours() * 60 + local.getMinutes();
const timeStr = String(local.getHours()).padStart(2,'0') + ':' + String(local.getMinutes()).padStart(2,'0');

let activeWindow = null;
for (const w of schedule) {
  if (!w.enabled || w.day !== currentDay) continue;
  const [sh, sm] = String(w.start).split(':').map(v => parseInt(v, 10));
  const [eh, em] = String(w.end).split(':').map(v => parseInt(v, 10));
  const startMin = sh * 60 + sm;
  const endMin = eh * 60 + em;
  // Overnight window support: 23:00-01:00
  let match;
  if (startMin <= endMin) {
    match = nowMin >= startMin && nowMin < endMin;
  } else {
    match = nowMin >= startMin || nowMin < endMin;
  }
  if (match) { activeWindow = w; break; }
}

msg.kind = 'desired_update';
msg.desiredModeNow = activeWindow ? (activeWindow.mode || 'run') : 'off';
msg.requiredBreakerState = msg.desiredModeNow === 'run' ? 'closed' : 'open';
msg.activeWindowId = activeWindow ? activeWindow.id : null;

node.status({fill:'blue',shape:'dot',text:`${currentDay} ${timeStr} → ${msg.desiredModeNow}`});

const state = flow.get('devxx_state') || {};
const audit = {
  ts: Date.now(), deviceId: 'DEVXX', channel: 'expected',
  sourceLayer: 'scenario', eventType: 'desired_evaluated',
  phase: state.phase || 'boot',
  desiredMode: msg.desiredModeNow,
  requiredBreakerState: msg.requiredBreakerState,
  actualBreakerState: state.actualBreakerState || null,
  healthMode: state.healthMode || null,
  ticketId: (state.ticket || {}).id || null,
  attemptNo: (state.ticket || {}).attemptCount || 0,
  result: msg.activeWindowId || 'outside_window',
  reasonCode: 'scenario_eval'
};
return [msg, {auditRecord: audit}];

// Normalize HA state to open/closed/unknown
// ⚠ DUPLICATED: also in fn_verify. Keep in sync.
function normalize(raw) {
  const s = String(raw).toLowerCase().trim();
  if (s === 'unavailable' || s === 'unknown' || s === 'null' || s === '') return 'unknown';
  if (s === 'on' || s === 'true' || s === 'open') return 'open';
  if (s === 'off' || s === 'false' || s === 'closed') return 'closed';
  return 'unknown';
}
const actual = normalize(msg.payload);
msg.kind = 'breaker_event';
msg.actualBreakerState = actual;

node.status({fill: actual === 'unknown' ? 'red' : 'green', shape:'dot', text: actual + ' (' + (msg.guardianSource||'event') + ')'});

const state = flow.get('devxx_state') || {};
msg.auditRecord = {
  ts: Date.now(), deviceId: 'DEVXX', channel: 'actual',
  sourceLayer: 'feedback', eventType: 'breaker_event',
  phase: state.phase || 'boot',
  desiredMode: state.desiredModeNow || null,
  requiredBreakerState: state.requiredBreakerState || null,
  actualBreakerState: actual,
  healthMode: actual === 'unknown' ? 'comm_lost' : 'healthy',
  ticketId: (state.ticket || {}).id || null,
  attemptNo: (state.ticket || {}).attemptCount || 0,
  result: msg.guardianSource || 'event',
  reasonCode: actual === 'unknown' ? 'feedback_unknown' : 'feedback_seen'
};
return [msg, {auditRecord: msg.auditRecord}];

// ================================================================
// COORDINATOR / STATE MACHINE v4
// Single phase owner. All decisions flow through this node.
// KEY FIX from v3: Starts with healthMode 'healthy' (optimistic).
// Only degrades to comm_lost on evidence (unknown feedback).
// ================================================================

const policy = flow.get('devxx_policy') || {
  retryDelaysSec: [5,15,60,180,300], keepRetrying: true,
  alarmPolicy: {enabled:false, maxAttempts:null, maxMismatchMinutes:null}
};

let state = flow.get('devxx_state');
if (!state) {
  state = {
    deviceId: 'DEVXX',
    desiredModeNow: 'off',
    requiredBreakerState: 'open',
    activeWindowId: null,
    actualBreakerState: 'unknown',
    phase: 'boot',
    healthMode: 'healthy',    // ← OPTIMISTIC START (v3 used 'uncertain' which blocked everything)
    recoveryMode: 'idle',
    ticket: null,
    lastConfirmedAt: null,
    lastObservedAt: null,
    lastDecisionReason: 'init',
    lastErrorClass: null,
    mismatchSince: null,
    lastStallHandledAt: null
  };
}

function save() { flow.set('devxx_state', state); }
function tid() { return 't_' + Date.now(); }

function updateStatus() {
  const colors = {
    'steady_ok':'green','boot':'grey','comm_lost':'red',
    'dispatching_open':'yellow','dispatching_close':'yellow',
    'verifying_open':'blue','verifying_close':'blue',
    'retry_backoff_open':'yellow','retry_backoff_close':'yellow',
    'reconciling':'blue','alarm':'red','steady_mismatch':'red'
  };
  const ti = state.ticket ? `T#${state.ticket.attemptCount}` : 'no-ticket';
  node.status({
    fill: colors[state.phase] || 'grey',
    shape: state.ticket ? 'ring' : 'dot',
    text: `${state.phase} | act:${state.actualBreakerState} req:${state.requiredBreakerState} | ${state.healthMode} | ${ti}`
  });
}

function audit(sl, et, result, rc) {
  return {
    ts: Date.now(), deviceId: 'DEVXX', channel: 'actual',
    sourceLayer: sl, eventType: et, phase: state.phase,
    desiredMode: state.desiredModeNow,
    requiredBreakerState: state.requiredBreakerState,
    actualBreakerState: state.actualBreakerState,
    healthMode: state.healthMode,
    ticketId: (state.ticket||{}).id||null,
    attemptNo: (state.ticket||{}).attemptCount||0,
    result, reasonCode: rc
  };
}

function nextDelay(n) {
  const l = (policy.retryDelaysSec && policy.retryDelaysSec.length) ? policy.retryDelaysSec : [5,15,60,180,300];
  return Number(l[Math.min(Math.max(n-1,0), l.length-1)]) || 5;
}

function alarmReached() {
  const ap = policy.alarmPolicy || {};
  if (!ap.enabled) return false;
  if (ap.maxAttempts != null && state.ticket && state.ticket.attemptCount >= Number(ap.maxAttempts)) return true;
  if (ap.maxMismatchMinutes != null && state.mismatchSince && (Date.now()-state.mismatchSince)/60000 >= Number(ap.maxMismatchMinutes)) return true;
  return false;
}

function openTicket(source) {
  if (!state.ticket) {
    state.ticket = { id:tid(), requestedBreakerState:state.requiredBreakerState, sourceLayer:source, attemptCount:0, createdAt:Date.now(), lastAttemptAt:null, status:'planned' };
  } else {
    state.ticket.requestedBreakerState = state.requiredBreakerState;
    state.ticket.sourceLayer = source;
  }
}

function makeDispatch(source) {
  openTicket(source);
  state.ticket.attemptCount += 1;
  state.ticket.status = 'dispatching';
  state.ticket.lastAttemptAt = Date.now();
  state.phase = state.requiredBreakerState === 'open' ? 'dispatching_open' : 'dispatching_close';
  state.lastDecisionReason = 'dispatch_' + state.requiredBreakerState;
  if (!state.mismatchSince) state.mismatchSince = Date.now();
  save();
  return {
    kind:'dispatch_request',
    command: state.requiredBreakerState === 'open' ? 'open' : 'close',
    ticketId: state.ticket.id,
    attemptNo: state.ticket.attemptCount,
    requestedBreakerState: state.requiredBreakerState
  };
}

function clearOK() {
  if (state.ticket) state.ticket.status = 'confirmed';
  state.ticket = null;
  state.phase = 'steady_ok';
  state.lastConfirmedAt = Date.now();
  state.lastErrorClass = null;
  state.mismatchSince = null;
  state.recoveryMode = 'idle';
}

function holdMM() {
  state.phase = 'steady_mismatch';
  if (!state.mismatchSince) state.mismatchSince = Date.now();
}

// ==================== DESIRED UPDATE ====================
if (msg.kind === 'desired_update') {
  state.desiredModeNow = msg.desiredModeNow;
  state.requiredBreakerState = msg.requiredBreakerState;
  state.activeWindowId = msg.activeWindowId;

  // DISPATCH COLLISION GUARD
  if (state.ticket && state.ticket.status !== 'confirmed' && state.ticket.requestedBreakerState !== state.requiredBreakerState) {
    state.ticket.status = 'superseded';
    state.ticket = null;
    const d = makeDispatch('scenario_direction_change');
    updateStatus();
    return [d, {auditRecord:audit('coordinator','ticket_superseded','dispatch','direction_reversal')}, {payload:state,kind:'state_snapshot'}];
  }

  if (state.healthMode === 'comm_lost') {
    holdMM(); updateStatus(); save();
    return [null, {auditRecord:audit('coordinator','desired_held','held','comm_lost')}, {payload:state,kind:'state_snapshot'}];
  }

  if (state.actualBreakerState === state.requiredBreakerState) {
    clearOK(); updateStatus(); save();
    return [null, {auditRecord:audit('coordinator','desired_satisfied','ok','match')}, {payload:state,kind:'state_snapshot'}];
  }

  const d = makeDispatch('scenario');
  updateStatus();
  return [d, {auditRecord:audit('coordinator','ticket_opened','dispatch','scenario_change')}, {payload:state,kind:'state_snapshot'}];
}

// ==================== BREAKER EVENT ====================
if (msg.kind === 'breaker_event') {
  state.actualBreakerState = msg.actualBreakerState;
  state.lastObservedAt = Date.now();

  if (msg.actualBreakerState === 'unknown') {
    state.phase = 'comm_lost';
    state.healthMode = 'comm_lost';
    state.lastErrorClass = 'feedback_unknown';
    updateStatus(); save();
    return [null, {auditRecord:audit('coordinator','health_comm_lost','comm_lost','feedback_unknown')}, {payload:state,kind:'state_snapshot'}];
  }

  state.healthMode = 'healthy';

  // Recovery from comm_lost
  if (state.phase === 'comm_lost' || state.recoveryMode === 'reconcile_pending') {
    state.recoveryMode = 'active';
    state.phase = 'reconciling';
    if (state.actualBreakerState === state.requiredBreakerState) {
      clearOK(); updateStatus(); save();
      return [null, {auditRecord:audit('coordinator','reconcile_ok','ok','compliant')}, {payload:state,kind:'state_snapshot'}];
    }
    const d = makeDispatch('reconcile');
    updateStatus();
    return [d, {auditRecord:audit('coordinator','reconcile_dispatch','dispatch','mismatch_after_restore')}, {payload:state,kind:'state_snapshot'}];
  }

  if (state.actualBreakerState === state.requiredBreakerState) {
    clearOK(); updateStatus(); save();
    return [null, {auditRecord:audit('coordinator','state_match','ok','match')}, {payload:state,kind:'state_snapshot'}];
  }

  if (!state.ticket && state.requiredBreakerState) {
    // Stall debounce
    if (msg.guardianSource === 'stall_watch') {
      if (state.lastStallHandledAt && (Date.now() - state.lastStallHandledAt) < 300000) {
        holdMM(); updateStatus(); save();
        return [null, {auditRecord:audit('coordinator','stall_debounced','skip','recent')}, {payload:state,kind:'state_snapshot'}];
      }
      state.lastStallHandledAt = Date.now();
    }
    const d = makeDispatch(msg.guardianSource === 'stall_watch' ? 'guardian_stall' : 'guardian');
    updateStatus();
    return [d, {auditRecord:audit('coordinator','guardian_correction','dispatch','mismatch')}, {payload:state,kind:'state_snapshot'}];
  }

  holdMM(); updateStatus(); save();
  return [null, {auditRecord:audit('coordinator','mismatch_wait','wait','ticket_active')}, {payload:state,kind:'state_snapshot'}];
}

// ==================== DISPATCH ACK ====================
if (msg.kind === 'dispatch_ack') {
  if (!state.ticket || msg.ticketId !== state.ticket.id) {
    updateStatus(); save();
    return [null, {auditRecord:audit('coordinator','ack_ignored','ignored','ticket_mismatch')}, {payload:state,kind:'state_snapshot'}];
  }
  state.ticket.status = 'awaiting_feedback';
  state.phase = state.ticket.requestedBreakerState === 'open' ? 'verifying_open' : 'verifying_close';
  updateStatus(); save();
  return [null, {auditRecord:audit('coordinator','dispatch_ack','verifying','started')}, {payload:state,kind:'state_snapshot'}];
}

// ==================== DISPATCH ERROR ====================
if (msg.kind === 'dispatch_error') {
  state.lastErrorClass = 'dispatch_error';
  if (!state.ticket) { updateStatus(); save(); return [null, {auditRecord:audit('coordinator','error_no_ticket','ignored','no_ticket')}, {payload:state,kind:'state_snapshot'}]; }
  if (alarmReached() || !policy.keepRetrying) {
    state.phase = 'alarm'; state.ticket.status = 'alarm'; updateStatus(); save();
    return [null, {auditRecord:audit('coordinator','alarm','alarm','dispatch_error')}, {payload:state,kind:'state_snapshot'}];
  }
  const ds = nextDelay((state.ticket.attemptCount||0)+1);
  state.phase = state.ticket.requestedBreakerState === 'open' ? 'retry_backoff_open' : 'retry_backoff_close';
  state.ticket.status = 'backoff_wait'; updateStatus(); save();
  return [null, {auditRecord:audit('coordinator','retry_after_error','delay_'+ds+'s','dispatch_error')}, {payload:state,kind:'retry_wait',delay:ds*1000}];
}

// ==================== VERIFY RESULT ====================
if (msg.kind === 'verify_result') {
  if (!state.ticket || msg.ticketId !== state.ticket.id) {
    updateStatus(); save();
    return [null, {auditRecord:audit('coordinator','verify_ignored','ignored','ticket_mismatch')}, {payload:state,kind:'state_snapshot'}];
  }
  state.actualBreakerState = msg.actualBreakerState || state.actualBreakerState;
  state.lastObservedAt = Date.now();
  if (msg.verifyStatus === 'confirmed') {
    clearOK(); updateStatus(); save();
    return [null, {auditRecord:audit('coordinator','verified_ok','ok','confirmed')}, {payload:state,kind:'state_snapshot'}];
  }
  if (msg.verifyStatus === 'uncertain') {
    state.healthMode = 'comm_lost'; state.phase = 'comm_lost';
    state.lastErrorClass = 'verify_uncertain'; state.recoveryMode = 'reconcile_pending';
    updateStatus(); save();
    return [null, {auditRecord:audit('coordinator','verify_uncertain','held','unknown')}, {payload:state,kind:'state_snapshot'}];
  }
  if (alarmReached() || !policy.keepRetrying) {
    state.phase = 'alarm'; state.ticket.status = 'alarm'; state.lastErrorClass = 'verify_mismatch';
    updateStatus(); save();
    return [null, {auditRecord:audit('coordinator','alarm','alarm','verify_mismatch')}, {payload:state,kind:'state_snapshot'}];
  }
  const ds = nextDelay((state.ticket.attemptCount||0)+1);
  state.phase = state.ticket.requestedBreakerState === 'open' ? 'retry_backoff_open' : 'retry_backoff_close';
  state.ticket.status = 'backoff_wait'; state.lastErrorClass = 'verify_mismatch';
  updateStatus(); save();
  return [null, {auditRecord:audit('coordinator','retry_scheduled','delay_'+ds+'s','verify_failed')}, {payload:state,kind:'retry_wait',delay:ds*1000}];
}

// ==================== RETRY ELAPSED ====================
if (msg.kind === 'retry_elapsed') {
  if (!state.ticket) { updateStatus(); save(); return [null, {auditRecord:audit('coordinator','retry_no_ticket','noop','none')}, {payload:state,kind:'state_snapshot'}]; }
  if (state.actualBreakerState === state.requiredBreakerState) { clearOK(); updateStatus(); save(); return [null, {auditRecord:audit('coordinator','retry_not_needed','ok','match')}, {payload:state,kind:'state_snapshot'}]; }
  if (state.healthMode === 'comm_lost') { state.recoveryMode = 'reconcile_pending'; updateStatus(); save(); return [null, {auditRecord:audit('coordinator','retry_blocked','held','comm_lost')}, {payload:state,kind:'state_snapshot'}]; }
  const d = makeDispatch('retry');
  updateStatus();
  return [d, {auditRecord:audit('coordinator','retry_dispatch','dispatch','elapsed')}, {payload:state,kind:'state_snapshot'}];
}

// ==================== MANUAL RECONCILE ====================
if (msg.kind === 'manual_reconcile') {
  state.phase = 'reconciling'; state.recoveryMode = 'manual';
  if (state.actualBreakerState === state.requiredBreakerState && state.actualBreakerState !== 'unknown') {
    clearOK(); updateStatus(); save();
    return [null, {auditRecord:audit('coordinator','reconcile_ok','ok','compliant')}, {payload:state,kind:'state_snapshot'}];
  }
  if (state.healthMode !== 'comm_lost') {
    const d = makeDispatch('reconcile');
    updateStatus();
    return [d, {auditRecord:audit('coordinator','reconcile_dispatch','dispatch','manual')}, {payload:state,kind:'state_snapshot'}];
  }
  updateStatus(); save();
  return [null, {auditRecord:audit('coordinator','reconcile_held','held','comm_lost')}, {payload:state,kind:'state_snapshot'}];
}

// ==================== MANUAL RESET ====================
if (msg.kind === 'manual_reset') {
  const old = state.phase;
  state.phase = 'boot'; state.ticket = null; state.healthMode = 'healthy';
  state.recoveryMode = 'idle'; state.lastErrorClass = null;
  state.mismatchSince = null; state.lastStallHandledAt = null;
  state.lastDecisionReason = 'manual_reset from ' + old;
  updateStatus(); save();
  return [null, {auditRecord:audit('coordinator','manual_reset','reset','from_'+old)}, {payload:state,kind:'state_snapshot'}];
}

// ==================== HA READ ERROR ====================
if (msg.kind === 'ha_read_error') {
  state.lastErrorClass = 'ha_read_error';
  node.warn('[DEVXX] HA read error — system continues healthy. Error: ' + ((msg.error||{}).message||'unknown'));
  updateStatus(); save();
  return [null, {auditRecord:audit('coordinator','ha_read_error','warn','read_failed')}, {payload:state,kind:'state_snapshot'}];
}

// ==================== PHASE TIMEOUT ====================
if (msg.kind === 'phase_timeout') {
  state.lastErrorClass = 'phase_timeout';
  state.lastDecisionReason = 'timeout: ' + msg.stalePhase + ' ' + msg.elapsedMs + 'ms';
  if (alarmReached()) {
    state.phase = 'alarm'; if (state.ticket) state.ticket.status = 'alarm';
    updateStatus(); save();
    return [null, {auditRecord:audit('coordinator','alarm','alarm','phase_timeout')}, {payload:state,kind:'state_snapshot'}];
  }
  if (state.ticket && state.healthMode !== 'comm_lost') {
    const ds = nextDelay((state.ticket.attemptCount||0)+1);
    state.phase = state.ticket.requestedBreakerState === 'open' ? 'retry_backoff_open' : 'retry_backoff_close';
    state.ticket.status = 'backoff_wait'; updateStatus(); save();
    return [null, {auditRecord:audit('coordinator','retry_after_timeout','delay_'+ds+'s','timeout')}, {payload:state,kind:'retry_wait',delay:ds*1000}];
  }
  holdMM(); updateStatus(); save();
  return [null, {auditRecord:audit('coordinator','timeout_held','held','no_ticket')}, {payload:state,kind:'state_snapshot'}];
}

// ==================== UNKNOWN ====================
updateStatus(); save();
return [null, {auditRecord:audit('coordinator','ignored','ignored','unknown_kind')}, {payload:state,kind:'state_snapshot'}];

const policy = flow.get('devxx_policy') || {};
const state = flow.get('devxx_state') || {};
const ackMsg = {
  kind: 'dispatch_ack',
  ticketId: msg.ticketId || ((state.ticket||{}).id||null),
  attemptNo: msg.attemptNo || ((state.ticket||{}).attemptCount||0)
};
const auditMsg = {
  auditRecord: {
    ts: Date.now(), deviceId: 'DEVXX', channel: 'actual',
    sourceLayer: 'dispatcher', eventType: 'dispatch_sent',
    phase: state.phase || 'dispatching',
    desiredMode: state.desiredModeNow || null,
    requiredBreakerState: state.requiredBreakerState || null,
    actualBreakerState: state.actualBreakerState || null,
    healthMode: state.healthMode || null,
    ticketId: ackMsg.ticketId, attemptNo: ackMsg.attemptNo,
    result: msg.command || 'sent', reasonCode: 'service_sent'
  }
};
const verifyMsg = {
  ticketId: ackMsg.ticketId,
  attemptNo: ackMsg.attemptNo,
  delay: policy.verifyAfterMs || 8000
};
node.status({fill:'yellow',shape:'dot',text:'Sent: ' + (msg.command||'?')});
return [ackMsg, auditMsg, verifyMsg];

// Normalize HA state to open/closed/unknown
// ⚠ DUPLICATED: also in fn_breaker_classify. Keep in sync.
function normalize(raw) {
  const s = String(raw).toLowerCase().trim();
  if (s === 'unavailable' || s === 'unknown' || s === 'null' || s === '') return 'unknown';
  if (s === 'on' || s === 'true' || s === 'open') return 'open';
  if (s === 'off' || s === 'false' || s === 'closed') return 'closed';
  return 'unknown';
}
const state = flow.get('devxx_state') || {};
const actual = normalize(msg.payload);
const ticket = state.ticket || {};
msg.kind = 'verify_result';
msg.ticketId = ticket.id || msg.ticketId || null;
msg.actualBreakerState = actual;
msg.verifyStatus = actual === 'unknown' ? 'uncertain' : (actual === state.requiredBreakerState ? 'confirmed' : 'mismatch');

node.status({fill: msg.verifyStatus === 'confirmed' ? 'green' : 'red', shape:'dot', text: msg.verifyStatus + ': ' + actual});

const audit = {
  ts: Date.now(), deviceId: 'DEVXX', channel: 'actual',
  sourceLayer: 'verifier', eventType: 'verify_result',
  phase: state.phase || 'verifying',
  desiredMode: state.desiredModeNow || null,
  requiredBreakerState: state.requiredBreakerState || null,
  actualBreakerState: actual, healthMode: state.healthMode || null,
  ticketId: msg.ticketId, attemptNo: ticket.attemptCount || 0,
  result: msg.verifyStatus, reasonCode: 'post_dispatch_check'
};
return [msg, {auditRecord: audit}];

const state = flow.get('devxx_state') || {};
const TIMEOUTS = {
  'dispatching_open': 30000, 'dispatching_close': 30000,
  'verifying_open': 20000, 'verifying_close': 20000,
  'retry_backoff_open': 330000, 'retry_backoff_close': 330000,
  'reconciling': 60000
};
const maxMs = TIMEOUTS[state.phase];
if (!maxMs) return null;
const ref = (state.ticket && state.ticket.lastAttemptAt) ? state.ticket.lastAttemptAt
  : (state.ticket && state.ticket.createdAt) ? state.ticket.createdAt : Date.now();
const elapsed = Date.now() - ref;
if (elapsed > maxMs) {
  msg.kind = 'phase_timeout';
  msg.stalePhase = state.phase;
  msg.elapsedMs = elapsed;
  node.status({fill:'red',shape:'ring',text:'TIMEOUT: ' + state.phase});
  msg.auditRecord = {
    ts: Date.now(), deviceId: 'DEVXX', channel: 'actual',
    sourceLayer: 'watchdog', eventType: 'phase_timeout',
    phase: state.phase, desiredMode: state.desiredModeNow || null,
    requiredBreakerState: state.requiredBreakerState || null,
    actualBreakerState: state.actualBreakerState || null,
    healthMode: state.healthMode || null,
    ticketId: (state.ticket||{}).id || null,
    attemptNo: (state.ticket||{}).attemptCount || 0,
    result: 'timeout_' + elapsed + 'ms',
    reasonCode: 'phase_exceeded_' + maxMs + 'ms'
  };
  return [msg, {auditRecord: msg.auditRecord}];
}
node.status({fill:'green',shape:'dot',text:'OK: ' + state.phase});
return null;

const state = flow.get('devxx_state') || {};
const READ_NODE_IDS = ['cur_boot_breaker', 'cur_breaker'];
const sourceId = ((msg.error||{}).source||{}).id || '';
const sourceName = ((msg.error||{}).source||{}).name || sourceId;
const isRead = READ_NODE_IDS.includes(sourceId);
msg.kind = isRead ? 'ha_read_error' : 'dispatch_error';
msg.ticketId = ((state.ticket||{}).id) || null;
msg.errorSource = sourceName;

node.status({fill:'red',shape:'ring',text: msg.kind + ': ' + sourceName});

msg.auditRecord = {
  ts: Date.now(), deviceId: 'DEVXX', channel: 'actual',
  sourceLayer: 'catch', eventType: msg.kind,
  phase: state.phase || 'boot',
  desiredMode: state.desiredModeNow || null,
  requiredBreakerState: state.requiredBreakerState || null,
  actualBreakerState: state.actualBreakerState || null,
  healthMode: state.healthMode || null,
  ticketId: msg.ticketId,
  attemptNo: ((state.ticket||{}).attemptCount) || 0,
  result: sourceName,
  reasonCode: ((msg.error||{}).message) || 'ha_error'
};
return [msg, {auditRecord: msg.auditRecord}];

const policy = flow.get('devxx_policy') || { journalLimit: 500 };
const rec = msg.auditRecord;
if (!rec) return null;
const expected = flow.get('devxx_expected_journal') || [];
const actual = flow.get('devxx_actual_journal') || [];
const line = { ...rec, iso: new Date(rec.ts).toISOString() };
if (rec.channel === 'expected') expected.push(line); else actual.push(line);
// Efficient trim with splice instead of while/shift
if (expected.length > policy.journalLimit) expected.splice(0, expected.length - policy.journalLimit);
if (actual.length > policy.journalLimit) actual.splice(0, actual.length - policy.journalLimit);
flow.set('devxx_expected_journal', expected);
flow.set('devxx_actual_journal', actual);

node.status({fill:'grey',shape:'dot',text: rec.eventType + ' [' + rec.channel + ']'});

msg.payload = line;
return msg;

const state = flow.get('devxx_state') || {};
const expected = flow.get('devxx_expected_journal') || [];
const actual = flow.get('devxx_actual_journal') || [];
const out = [];
out.push('=== DEVXX CONTROL REPORT v4 ===');
out.push('Generated: ' + new Date().toISOString());
out.push('');
out.push('Current State:');
out.push(JSON.stringify(state, null, 2));
out.push('');
out.push('Last 10 Expected Journal:');
out.push(JSON.stringify(expected.slice(-10).reverse(), null, 2));
out.push('');
out.push('Last 20 Actual Journal:');
out.push(JSON.stringify(actual.slice(-20).reverse(), null, 2));
msg.payload = out.join('\n');
return msg;
